-- Seeds the original Palm Spring quiz. Safe to re-run (upserts by id).
insert into public.quizzes (id,title,jokers,rounds) values ('a0000000-0000-4000-8000-000000000001','Palm Spring Quiz Night',true,'[{"name":"Round 1 · General Knowledge","type":"normal","ptsPerQ":1,"questions":[["The Mekong River flows through how many countries?","6 — China, Myanmar, Laos, Thailand, Cambodia, and Vietnam"],["What is the capital of New Zealand?","Wellington",["Auckland","Wellington","Christchurch","Hamilton"]],["Which chemical element has the symbol Pb?","Lead"],["Areca is one of the names of the Palm Spring blocks — name at least 2 other blocks.","Areca (Block 16)\nRoyal (Block 18)\nSolitaire (Block 20)\nJamaica (Block 22)"],["Which is the largest ocean on Earth?","Pacific Ocean"],["Which of these is NOT a Nobel Prize category?","Mathematics",["Physics","Chemistry","Literature","Mathematics"]],["The Suez Canal connects which two seas?","Mediterranean Sea and Red Sea"],["How many squares are there on a standard chessboard?","64"],["What is the longest bone in the human body?","Femur"],["In which year was Ion Orchard built?","C) 2009 (opened 21 July 2009)",["2011","2015","2009","2007"]]]},{"name":"Round 2 · Music: Name That Tune","type":"music","ptsPerQ":1,"questions":[["Clip 1","How Deep Is Your Love — Bee Gees"],["Clip 2","Set Fire to the Rain — Adele"],["Clip 3","Take On Me — a-ha"],["Clip 4","Locked Out of Heaven — Bruno Mars"],["Clip 5","Paparazzi — Lady Gaga"],["Clip 6","Don''t Start Now — Dua Lipa"],["Clip 7","Love Story — Taylor Swift"],["Clip 8","Lovefool — The Cardigans"],["Clip 9","Don''t Look Back in Anger — Oasis"],["Clip 10","Titanium — David Guetta, Sia"]]},{"name":"Round 3 · Movies, TV and Media","type":"normal","ptsPerQ":1,"questions":[["What is the surname of the boxer played by Sylvester Stallone in Rocky?","Balboa"],["What is Indiana Jones''s profession?","Archaeologist",["Detective","Archaeologist","Doctor","Journalist"]],["What is the name of the teenager who travels through time in Back to the Future? (first and last name)","Marty McFly"],["In the movie \"The Lion King\", what is the name of Simba''s father?","Mufasa"],["In the TV show Friends, what is the full name of Ross'' sister? (first and last name)","Monica Geller"],["Which country is the author of Tintin from?","Belgium",["France","Belgium","Luxembourg","Morocco"]],["Name the next movie in this sequence: The Sorcerer''s Stone, Chamber of Secrets, The Prisoner of Azkaban, and __.","Goblet of Fire"],["What was the first feature-length film to be completely computer-animated?","Toy Story"],["Which movie contains the iconic quote: \"Life is like a box of chocolates. You never know what you''re gonna get.\"","Forrest Gump"],["In the 2023 Barbie film, which character is played by Ryan Gosling?","Ken"]]},{"name":"Round 4 · Picture Round: Logos (on paper)","type":"picture","ptsPerQ":1,"questions":[["Logo 1","Rolex"],["Logo 2","Airbnb"],["Logo 3","Quaker Oats"],["Logo 4","Umbro"],["Logo 5","Guinness"],["Logo 6","Popular"],["Logo 7","Adobe"],["Logo 8","DreamWorks"],["Logo 9","Maserati"],["Logo 10","National Geographic"]]},{"name":"Round 5 · Sports — Something or Nothing","type":"normal","ptsPerQ":2,"questions":[["We all know that Joseph Schooling won the first Olympic gold medal for Singapore in 2016. Which event specifically was it for?","Men''s 100 m butterfly"],["What is the name of the street circuit used for the Formula 1 Singapore Grand Prix?","Marina Bay Street Circuit"],["Who was the first person to run a mile in under 4 minutes?","Roger Bannister",["Roger Bannister","Jesse Owens","John Landy","Mo Farah"]],["Who was the first boxer to beat Muhammad Ali?","Joe Frazier"],["How often are the Southeast Asian (SEA) Games normally held?","Every 2 years"]],"allOrNothing":true}]'::jsonb)
  on conflict (id) do update set title=excluded.title, jokers=excluded.jokers, rounds=excluded.rounds;
